<script setup lang="ts">
import {ref} from 'vue'
const token=ref(''),status=ref('尚未检测'),message=ref(''),rows=ref<{id:string;name:string}[]>([]),name=ref(''),busy=ref(false),file=ref<File>(),link=ref('')
async function request(path:string,options:RequestInit={}){const response=await fetch('/api/'+path,{...options,headers:{...options.headers,Authorization:'Bearer '+token.value}});const data=await response.json();if(!response.ok)throw new Error(data.error||'请求失败');return data}
async function run(action:()=>Promise<void>){busy.value=true;message.value='';try{await action()}catch(e){message.value=e instanceof Error?e.message:'连接失败'}finally{busy.value=false}}
function health(){run(async()=>{const d=await request('health');status.value=`MySQL：${d.database}；COS：${d.cos}`})}
function load(){run(async()=>{rows.value=await request('customers');message.value='已读取真实数据库'})}
function add(){run(async()=>{await request('customers',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:name.value})});name.value='';rows.value=await request('customers');message.value='客户已写入 MySQL'})}
function upload(){run(async()=>{if(!file.value)return;const body=new FormData();body.append('file',file.value);const d=await request('files',{method:'POST',body});link.value=d.url;message.value='已上传 COS；预览链接有效期 5 分钟'})}
</script>
<template><section class="panel spaced"><h2>本地后端连接验证</h2><p>此区域访问真实 API；与现有模拟 CRM 分开，避免意外覆盖数据。访问令牌仅保留在当前页面内存。</p><p>{{status}}</p><button :disabled="busy" @click="health">检测连接</button><label>本机 API 访问令牌<input v-model="token" type="password" autocomplete="off" placeholder="填写 .env 中的 API_TOKEN"/></label><div class="backend-actions"><input v-model="name" placeholder="真实客户公司名称" aria-label="真实客户公司名称" maxlength="200"/><button :disabled="busy||!name.trim()" @click="add">写入 MySQL</button><button :disabled="busy" @click="load">读取客户</button></div><p v-for="r in rows" :key="r.id">{{r.name}}</p><label>上传产品图片 / PDF（最多 10MB）<input type="file" accept="image/png,image/jpeg,application/pdf" @change="file=($event.target as HTMLInputElement).files?.[0];link=''"/></label><button :disabled="busy||!file" @click="upload">上传到 COS</button><p v-if="link"><a :href="link" target="_blank" rel="noopener noreferrer">查看已上传文件 ↗</a></p><p role="status">{{message}}</p></section></template>
<style scoped>.backend-actions{display:flex;gap:10px;flex-wrap:wrap}.backend-actions input{flex:1;min-width:160px}a{color:#2d6c61}</style>
